Reusable, independent pieces of UI.

```jsx
function Welcome(props) {
  return <h1>Hello, {props.name}</h1>;
}
```

Functional components are simpler functions. Class components use ES6 classes and have lifecycle methods.

```jsx
// Functional
function Welcome() {
  return <h1>Hello</h1>;
}

// Class
class Welcome extends React.Component {
  render() {
    return <h1>Hello</h1>;
  }
}
```

Properties passed from parent to child components (read-only).

```jsx
function Greeting(props) {
  return <h1>Hello, {props.name}</h1>;
}
<Greeting name="John" />
```

Mutable data managed within a component.

```jsx
function Counter() {
  const [count, setCount] = useState(0);
  return <button onClick={() => setCount(count + 1)}>{count}</button>;
}
```

Hook for side effects (data fetching, subscriptions, DOM manipulation).

```jsx
useEffect(() => {
  document.title = `Count: ${count}`;
}, [count]); // runs when count changes
```

Phases: Mounting, Updating, Unmounting.

```jsx
useEffect(() => {
  // mounting
  return () => {
    // unmounting
  };
}, []);
```

Rendering different content based on conditions.

```jsx
{isLoggedIn ? <Dashboard /> : <Login />}
{error && <ErrorMessage />}
```

Hook for accessing DOM elements or persisting values across renders without causing re-render.

```jsx
const inputRef = useRef(null);
inputRef.current.focus();
```

Way to pass data through component tree without props drilling.

```jsx
const ThemeContext = React.createContext('light');

function App() {
  return (
    <ThemeContext.Provider value="dark">
      <Child />
    </ThemeContext.Provider>
  );
}
```

Building complex components from simpler ones.

```jsx
function Layout({ children }) {
  return <div className="layout">{children}</div>;
}

<Layout>
  <Header />
  <Content />
</Layout>
```

Special prop containing content between component tags.

```jsx
function Card({ children }) {
  return <div className="card">{children}</div>;
}

<Card><p>Content</p></Card>
```

Default values for props.

```jsx
function Button({ label = "Click me" }) {
  return <button>{label}</button>;
}

// or
Button.defaultProps = {
  label: "Click me"
};
```
